sys_ux_data_broker_transform.script:
function transform(input) {
    // List of properties to be fetched from the system properties
    var kpiProperties = [
        'sam.implementation.euc',
        'sam.implementation.servers',
        'sam.current.installation.kpi',
        'sam.current.subscription.kpi'
    ];

    // Object to hold the KPI values for each type
    var kpiValues = {
        'euc_kpi': [],
        'server_kpi': [],
        'installation_kpi': [],
        'subscription_kpi': []
    };

    function calculateAveragePercentages(input) {
        var output = {};

        for (var key in input) {
            if (input.hasOwnProperty(key)) {
                var percentages = input[key].map(function(item) {
                    return item.percentage;
                });
                var average = Math.floor(
                    percentages.reduce(function(sum, value) {
                        return sum + value;
                    }, 0) / percentages.length
                );

                output[key] = input[key].map(function(item) {
                    var newItem = Object.assign({}, item);
                    newItem.average = average;
                    return newItem;
                });
            }
        }

        return output;
    }


    // Function to fetch and parse the KPIs
    function fetchKPIs(propertyName) {
        var kpis = [];
        var propertyValue = gs.getProperty(propertyName);

        if (propertyValue) {
            try {
                kpis = JSON.parse(propertyValue); // Parsing the JSON property
            } catch (e) {
                gs.log("Error parsing " + propertyName + ": " + e.message);
            }
        } else {
            gs.log("Property " + propertyName + " is not set or is empty.");
        }
        return kpis;
    }

    // Function to process each KPI and get the corresponding field value
    function processKPI(kpis, kpiType) {
        if (Array.isArray(kpis)) {
            kpis.forEach(function(kpi) {
                if (kpi.kpi && kpi.kpi.toLowerCase().indexOf('duplicate') !== -1) {
                    return; // Skip this KPI
                }
                if (kpi.description && kpi.description.toLowerCase().indexOf('duplicate') !== -1) {
                    return; // Skip this KPI
                }
                // Ensure kpi.table and kpi.query are present
                if (kpi.table && kpi.field) {
                    var queryCount = getQueryCount(kpi.table, kpi.field);
                    var totalCount = getTableTotalCount(kpi.table);
                    var percentage = parseInt((queryCount / totalCount) * 100);

                    kpiValues[kpiType].push({
                        'kpi': kpi.kpi,
                        'description': kpi.description,
                        'table': kpi.table,
                        'query_count': queryCount,
                        'total_count': totalCount,
                        'percentage': percentage,
                        'action': kpi.recommendation
                    });
                } else {
                    gs.log("KPI missing table or query: " + JSON.stringify(kpi));
                }
            });
        } else {
            gs.log("The " + kpiType + " property is not in the expected format.");
        }
    }

    // Loop through the KPI properties and process each one
    kpiProperties.forEach(function(property, index) {
        var kpiType = Object.keys(kpiValues)[index];
        var kpis = fetchKPIs(property);
        processKPI(kpis, kpiType);
    });

    // Function to get query count based on table and query
    function getQueryCount(tableName, field) {
        try {
            var gr = new GlideAggregate(tableName);
            gr.addEncodedQuery(field);
            gr.addAggregate('COUNT');
            gr.query();

            if (gr.next()) {
                return parseInt(gr.getAggregate('COUNT'), 10);
            }
            return 0;
        } catch (error) {
            gs.print("Error querying table: " + error.message);
            return 0; // Return 0 in case of an error
        }
    }

    // Function to get the total count of records in a table
    function getTableTotalCount(tableName) {
        try {
            var gr = new GlideAggregate(tableName);
            gr.addAggregate('COUNT');
            gr.query();

            if (gr.next()) {
                return parseInt(gr.getAggregate('COUNT'), 10);
            }
            return 0;
        } catch (error) {
            gs.print("Error querying table total count: " + error.message);
            return 0; // Return 0 in case of an error
        }
    }

    // Return the final KPI values object
    return calculateAveragePercentages(kpiValues);
}
